<div class="page-head"><div><p class="eyebrow">Sales</p><h1>Customer Management</h1><p>Add, view, edit and manage customer information.</p></div></div><section class="panel"><div class="panel-head"><h2><?=$edit?'Edit Customer':'Add Customer'?></h2></div><form method="post" data-validate-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>Customer Name</label><input name="name" value="<?=e($edit['name']??'')?>" required maxlength="120"></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($edit['phone']??'')?>" maxlength="40"></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=e($edit['email']??'')?>"></div><div class="field"><label>Address</label><input name="address" value="<?=e($edit['address']??'')?>" maxlength="255"></div></div><div class="form-actions"><button class="btn role-btn"><?=$edit?'✓ Update Customer':'＋ Add Customer'?></button><?php if($edit): ?><a class="btn gray" href="customers.php">Cancel</a><?php endif; ?></div></form></section><br><section class="panel"><div class="panel-head"><h2>All Customers</h2></div><div class="table-wrap"><table class="table"><tr><th>Name</th><th>Phone</th><th>Email</th><th>Address</th><th>Actions</th></tr><?php foreach($customers as $c): ?><tr><td><b><?=e($c['name'])?></b></td><td><?=e($c['phone']??'—')?></td><td><?=e($c['email']??'—')?></td><td><?=e($c['address']??'—')?></td><td class="actions"><a class="btn small role-btn" href="customers.php?edit=<?=$c['id']?>">✎ Edit</a><a class="btn small danger" data-confirm="Delete this customer?" href="customers.php?delete=<?=$c['id']?>">Delete</a></td></tr><?php endforeach; ?><?php if(!$customers): ?><tr><td colspan="5" class="empty">No customers found.</td></tr><?php endif; ?></table></div></section><?php require __DIR__.'/../../../includes/role_footer.php'; ?>
